declare eid uuid; c jsonb := $j${"schemaVersion":1,"id":"would-you-rather","title":"Would You Rather?","tagline":"Funny, surprising, work-safe choices.","emoji":"🤔","category":"icebreaker","description":"Ten quick dilemmas with no right answers. Everyone picks on their phone, then the room sees how the group split. A warm-up that gets people talking in under ten minutes.","durationMin":8,"players":{"min":3,"max":200},"languages":["en"],"ageRating":"all","facilitator":"optional","modes":["live","self","practice"],"defaultTiming":{"readSec":3,"answerSec":10},"reveal":"distribution","privacy":{"individualResults":false,"groupMinimum":3,"retainResponses":false},"scoring":{"kind":"aggregate","minAnsweredRatio":0},"transitions":["The room is split! 🤯","Who saw that coming? 👀","Strong opinions in here. 💬","Interesting choice, team. 🤔"],"closing":{"questions":["Which answer surprised you most?","Find someone who voted differently and ask why."],"message":"Different choices, one team. 💜"},"disclaimer":"Just for fun. No scores and no right answers. Only group totals are shown.","creator":"PulsePlay","status":"published","rounds":[{"id":"main","activities":[{"id":"w1","prompt":"Would you rather…","type":"poll","options":[{"id":"a","text":"Meetings with no slides","emoji":"🗂️"},{"id":"b","text":"Emails with no attachments","emoji":"📎"}]},{"id":"w2","prompt":"Would you rather…","type":"poll","options":[{"id":"a","text":"Present to 500 strangers","emoji":"🎤"},{"id":"b","text":"Sing happy birthday alone to your team","emoji":"🎂"}]},{"id":"w3","prompt":"Would you rather…","type":"poll","options":[{"id":"a","text":"Start every workday at 6:00","emoji":"🌅"},{"id":"b","text":"Finish every workday at 21:00","emoji":"🌙"}]},{"id":"w4","prompt":"Would you rather…","type":"poll","options":[{"id":"a","text":"One week without your phone","emoji":"📵"},{"id":"b","text":"One week without coffee or tea","emoji":"☕"}]},{"id":"w5","prompt":"Would you rather…","type":"poll","options":[{"id":"a","text":"Know every programming language","emoji":"🧠"},{"id":"b","text":"Speak every human language","emoji":"🗣️"}]},{"id":"w6","prompt":"Would you rather…","type":"poll","options":[{"id":"a","text":"Camera always on","emoji":"📹"},{"id":"b","text":"Always be the one who forgot to unmute","emoji":"🔇"}]},{"id":"w7","prompt":"Would you rather…","type":"poll","options":[{"id":"a","text":"Four-day week, longer days","emoji":"🏖️"},{"id":"b","text":"Five-day week, short days","emoji":"🕐"}]},{"id":"w8","prompt":"Would you rather…","type":"poll","options":[{"id":"a","text":"Slow Wi-Fi forever","emoji":"🐌"},{"id":"b","text":"Laptop battery that lasts one hour","emoji":"🔋"}]},{"id":"w9","prompt":"Would you rather…","type":"poll","options":[{"id":"a","text":"Have a mentor for life","emoji":"🦸"},{"id":"b","text":"Mentor someone for life","emoji":"🧭"}]},{"id":"w10","prompt":"Would you rather…","type":"poll","options":[{"id":"a","text":"Pick the team lunch forever","emoji":"🍕"},{"id":"b","text":"Pick the office playlist forever","emoji":"🎵"}]}]}]}$j$::jsonb; last jsonb;
